using System.IO;
using Microsoft.Data.Sqlite;
using System.Text;
namespace CardArchive;
internal static class Database
{
 private static readonly string Folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CardArchive");
 private static readonly string DbPath=Path.Combine(Folder,"Archive.db");
 private static string Cs=>new SqliteConnectionStringBuilder{DataSource=DbPath,Mode=SqliteOpenMode.ReadWriteCreate,Cache=SqliteCacheMode.Shared}.ToString();
 public static void Initialize(){Directory.CreateDirectory(Folder);using var c=new SqliteConnection(Cs);c.Open();using var q=c.CreateCommand();q.CommandText="PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS People(Id INTEGER PRIMARY KEY AUTOINCREMENT,FullName TEXT NOT NULL,CardNumber TEXT NOT NULL UNIQUE,CreatedAt TEXT NOT NULL); CREATE INDEX IF NOT EXISTS IX_People_FullName ON People(FullName);";q.ExecuteNonQuery();}
 public static List<Person> Search(string query=""){using var c=new SqliteConnection(Cs);c.Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,FullName,CardNumber,CreatedAt FROM People WHERE @q='' OR FullName LIKE @like OR CardNumber LIKE @like ORDER BY FullName COLLATE NOCASE,Id";q.Parameters.AddWithValue("@q",query.Trim());q.Parameters.AddWithValue("@like","%"+query.Trim()+"%");using var r=q.ExecuteReader();var a=new List<Person>();while(r.Read())a.Add(new Person{Id=r.GetInt64(0),FullName=r.GetString(1),CardNumber=r.GetString(2),CreatedAt=r.GetString(3)});return a;}
 public static long Count(){using var c=new SqliteConnection(Cs);c.Open();using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM People";return (long)q.ExecuteScalar()!;}
 public static void Add(string n,string no)=>Run("INSERT INTO People(FullName,CardNumber,CreatedAt) VALUES(@n,@c,@d)",n,no,null);
 public static void Update(long id,string n,string no)=>Run("UPDATE People SET FullName=@n,CardNumber=@c WHERE Id=@id",n,no,id);
 private static void Run(string sql,string n,string no,long? id){using var c=new SqliteConnection(Cs);c.Open();using var q=c.CreateCommand();q.CommandText=sql;q.Parameters.AddWithValue("@n",n.Trim());q.Parameters.AddWithValue("@c",no.Trim());if(sql.Contains("@d"))q.Parameters.AddWithValue("@d",DateTime.Now.ToString("s"));if(id.HasValue)q.Parameters.AddWithValue("@id",id.Value);q.ExecuteNonQuery();}
 public static void Delete(long id){using var c=new SqliteConnection(Cs);c.Open();using var q=c.CreateCommand();q.CommandText="DELETE FROM People WHERE Id=@id";q.Parameters.AddWithValue("@id",id);q.ExecuteNonQuery();}
 public static void Backup(string path){using var s=new SqliteConnection(Cs);s.Open();using var d=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=path}.ToString());d.Open();s.BackupDatabase(d);}
 public static (int added,int duplicates,int invalid) ImportCsv(string path){int a=0,d=0,b=0;using var sr=new StreamReader(path,true);using var c=new SqliteConnection(Cs);c.Open();using var tx=c.BeginTransaction();string? line;bool first=true;while((line=sr.ReadLine())!=null){if(string.IsNullOrWhiteSpace(line))continue;var f=Parse(line);if(first){first=false;if(f.Count>1&&(f[0].Contains("اسم")||f[0].Contains("name",StringComparison.OrdinalIgnoreCase)))continue;}if(f.Count<2||string.IsNullOrWhiteSpace(f[0])||string.IsNullOrWhiteSpace(f[1])){b++;continue;}using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT OR IGNORE INTO People(FullName,CardNumber,CreatedAt) VALUES(@n,@c,@d)";q.Parameters.AddWithValue("@n",f[0].Trim());q.Parameters.AddWithValue("@c",f[1].Trim());q.Parameters.AddWithValue("@d",DateTime.Now.ToString("s"));if(q.ExecuteNonQuery()==1)a++;else d++;}tx.Commit();return(a,d,b);}
 private static List<string> Parse(string s){var l=new List<string>();var v=new StringBuilder();bool quote=false;for(int i=0;i<s.Length;i++){char ch=s[i];if(ch=='"'){if(quote&&i+1<s.Length&&s[i+1]=='"'){v.Append('"');i++;}else quote=!quote;}else if(!quote&&(ch==','||ch==';'||ch=='\t')){l.Add(v.ToString());v.Clear();}else v.Append(ch);}l.Add(v.ToString());return l;}
}